(() => {
'use strict';
const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>(Number(v||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const when=v=>v?new Date(v*1000).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
const paths={bus:'M4 16h16V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v10Zm0-5h16M7 4V2m10 2V2M7 16v4m10-4v4M7 14h.01M17 14h.01',home:'m3 10 9-7 9 7M5 9v11h5v-6h4v6h5V9',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16',route:'M5 6a2 2 0 1 0 0 .01M19 18a2 2 0 1 0 0 .01M7 6h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8',wallet:'M3 7h17v14H3V4h15v3M15 12h6v5h-6z',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9L7.5 14 3 9.6l6.2-.9L12 3Z',arrow:'M5 12h14m-6-6 6 6-6 6',pin:'M12 21s7-7 7-12a7 7 0 1 0-14 0c0 5 7 12 7 12Zm0-15a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',gps:'M12 3v3m0 12v3M3 12h3m12 0h3M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10Z',user:'M20 21v-2a7 7 0 0 0-14 0v2M13 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',users:'M16 21v-2a5 5 0 0 0-10 0v2M11 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm7 1a4 4 0 0 1 0 8m1 3a5 5 0 0 1 3 5',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',info:'M12 8h.01M12 11v6m0-15a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',heart:'M20.8 4.6a5 5 0 0 0-7.1 0L12 6.3l-1.7-1.7a5 5 0 0 0-7.1 7.1L12 21l8.8-9.3a5 5 0 0 0 0-7.1Z',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',cloud:'M6 17a4 4 0 1 1 0-8h.4a6 6 0 0 1 11.2 0h.4a4 4 0 0 1 0 8H6Z',rain:'M6 15a4 4 0 1 1 0-8h.4a6 6 0 0 1 11.2 0h.4a4 4 0 0 1 0 8H6Zm2 3-1 3m6-3-1 3m6-3-1 3',card:'M3 5h18v14H3V5Zm0 5h18M6 15h4',pix:'m12 2 5 5-5 5-5-5 5-5Zm0 10 5 5-5 5-5-5 5-5ZM2 12l5-5 5 5-5 5-5-5Zm10 0 5-5 5 5-5 5-5-5Z',company:'M4 21V3h12v18M16 9h4v12M7 7h2m3 0h1M7 11h2m3 0h1M7 15h2m3 0h1M9 21v-3h3v3',logout:'M9 3H4v18h5M12 12h9m-4-4 4 4-4 4',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',refresh:'M20 7v5h-5M4 17v-5h5M5.1 7a8 8 0 0 1 13-2L20 8M4 16l1.9 3a8 8 0 0 0 13-2',plus:'M12 5v14M5 12h14',flag:'M5 22V3m0 0c5-4 9 4 14 0v10c-5 4-9-4-14 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4'};
const icon=(name,extra='')=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}><path d="${paths[name]||paths.info}"/></svg>`;
const S={user:null,me:null,lines:[],config:null,runs:[],wallet:null,reviews:[],tab:'explorar',authMode:'entrar',authRole:'passageiro',filter:'Todas',query:'',favorites:[],onlyFavorites:false,weather:null,weatherCity:'Maringá',weatherLoading:false,connected:true,selectedRun:null,points:[],plan:null,planLine:null,myLocation:null,alertArrival:false,alertShown:false,gpsSharing:false,gpsWatch:null,passWatch:null,lastGPS:0,mapCenter:null,mapZoom:13,paymentMethod:'pix',paymentKey:null,rating:0,reviewOccupancy:'medio'};
let map=null,mapLayers=null,mapMode=null,toastTimer=null,polling=false;
const app=$('#app'),modal=$('#modal');
const labelLot=x=>({vazio:'Vazio',medio:'Médio',cheio:'Cheio',superlotado:'Superlotado'}[x]||'Sem relato recente');
const lotClass=x=>({vazio:'green',medio:'green',cheio:'orange',superlotado:'red'}[x]||'');
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,6000);}
async function api(path,data,method){let response;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),18000);try{response=await fetch('/web-api/'+path,{method:method||(data===undefined?'GET':'POST'),credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal});S.connected=true;}catch(e){S.connected=false;throw Error(e.name==='AbortError'?'A consulta demorou demais. Tente novamente.':'Não foi possível acessar o servidor. Confira se a API está aberta.');}finally{clearTimeout(timer);}let result;try{result=await response.json();}catch{throw Error('O servidor não enviou uma resposta válida.');}if(!response.ok){let msg=Array.isArray(result.detail)?result.detail.map(x=>x.msg).join(' '):result.detail||'Não foi possível concluir.';const error=Error(msg);error.status=response.status;throw error;}return result;}
async function action(fn,button){if(button?.disabled)return;const old=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<span class="spinner"></span> Aguarde';}try{await fn();}catch(e){showError(e.message);if(e.status===401&&S.user){stopWatches();S.user=null;S.me=null;closeModal();render();}}finally{if(button?.isConnected){button.disabled=false;button.innerHTML=old;}}}
function showError(message){if(modal.open){let el=$('.modal-error',modal);if(!el){el=document.createElement('div');el.className='notice error modal-error';modal.prepend(el);}el.textContent=message;}else{const auth=$('#auth-error');if(auth){auth.textContent=message;auth.hidden=false;}else toast(message);}}
function logo(){return `<span class="logo"><span class="logo-mark">T<span>${icon('arrow')}</span></span><span><span class="logo-text">TRANS<b>URBAN</b></span><span class="brand-sub">Seu caminho, mais simples</span></span></span>`;}
function initials(){return S.user.nome.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();}
function saveFavorites(){try{localStorage.setItem('tu-favs-'+S.user.id,JSON.stringify(S.favorites));}catch{toast('Seu navegador não permitiu salvar os favoritos.');}}
function readFavorites(){try{const list=JSON.parse(localStorage.getItem('tu-favs-'+S.user.id)||'[]');S.favorites=Array.isArray(list)?list.filter(x=>typeof x==='string'):[];}catch{S.favorites=[];}}
function auth(){return `<div class="auth"><section class="auth-hero"><div>${logo()}</div><div class="auth-copy"><span class="upper" style="color:#6de5c5">MARINGÁ E SARANDI</span><h1>Seu caminho.<br><em>Mais simples.</em></h1><p>Informações de transporte, viagens colaborativas e cuidado com cada etapa do seu dia.</p><div class="auth-benefits"><div>${icon('route')} Escolha sua linha e acompanhe sua viagem</div><div>${icon('users')} Passageiros e motoristas no mesmo lugar</div><div>${icon('star')} Avaliações, lotação e sua experiência</div></div></div><div class="auth-footer"><span>Maringá</span><span></span><span>Sarandi</span></div></section><section class="auth-form-side"><div class="auth-panel"><span class="pill green">${icon('bus')} UMA NOVA EXPERIÊNCIA DE MOBILIDADE</span><h2>${S.authMode==='entrar'?'Bom ter você por aqui.':'Seu próximo destino começa aqui.'}</h2><p>${S.authMode==='entrar'?'Entre na sua conta para continuar a viagem.':'Crie sua conta neste ambiente de demonstração.'}</p><div class="auth-tabs"><button data-action="auth-mode" data-value="entrar" class="${S.authMode==='entrar'?'active':''}">Entrar</button><button data-action="auth-mode" data-value="criar" class="${S.authMode==='criar'?'active':''}">Criar conta</button></div>${S.authMode==='criar'?`<div class="segments"><button data-action="auth-role" data-value="passageiro" class="${S.authRole==='passageiro'?'active':''}">${icon('user')} Passageiro</button><button data-action="auth-role" data-value="motorista" class="${S.authRole==='motorista'?'active':''}">${icon('bus')} Motorista</button></div>`:''}<div id="auth-error" class="notice error" role="alert" hidden></div><form id="auth-form" class="form">${S.authMode==='criar'?'<label class="field">Como podemos chamar você?<input name="nome" autocomplete="name" minlength="2" maxlength="80" required placeholder="Seu nome"></label>':''}<label class="field">E-mail<input name="email" type="email" autocomplete="username" required maxlength="160" placeholder="voce@exemplo.com"></label><label class="field">Senha<div class="password"><input name="senha" type="password" autocomplete="${S.authMode==='criar'?'new-password':'current-password'}" minlength="${S.authMode==='criar'?8:1}" maxlength="128" required placeholder="${S.authMode==='criar'?'Crie uma senha com pelo menos 8 caracteres':'Digite sua senha'}"><button type="button" data-action="password">Mostrar</button></div></label><button type="submit" class="btn full">${S.authMode==='criar'?'Criar minha conta':'Entrar na minha conta'} ${icon('arrow')}</button></form><div class="notice warning" style="margin-top:22px">${icon('info')}<span>Demonstração acadêmica independente. Sem operação oficial de ônibus ou pagamentos reais. Motoristas são autodeclarados, sem verificação da operadora.</span></div><p class="auth-footnote">Contas são salvas no banco deste servidor. Não use a senha de outros serviços. Para testar os dois perfis, use uma janela normal e outra anônima.</p></div></section></div>`;}
function navItems(){return S.user.perfil==='motorista'?[['explorar','home','Meu painel'],['planejar','map','Planejar percurso'],['viagem','bus','Viagem ativa'],['avaliacoes','star','Avaliações'],['sobre','info','Sobre o projeto']]:[['explorar','search','Explorar linhas'],['viagem','route','Minha viagem'],['carteira','wallet','Meu passe'],['avaliacoes','star','Avaliações'],['sobre','info','Sobre o projeto']];}
function weather(){const w=S.weather;let symbol=w?(w.sugere_guarda_chuva?'rain':w.codigo_tempo<=1?'sun':'cloud'):'cloud';return `<div class="weather"><span class="weather-icon">${icon(symbol)}</span><div><strong>${w?esc(Math.round(w.temperatura_c))+'°':S.weatherLoading?'…':'—'}</strong><p>${w?`${w.probabilidade_chuva_percentual===null?'Chuva sem estimativa':esc(w.probabilidade_chuva_percentual)+'% de chance de chuva hoje'}`:S.weatherLoading?'Consultando previsão…':'Previsão indisponível'}</p><small>${w?(w.sugere_guarda_chuva?'Considere levar um guarda-chuva.':'Confira a previsão antes de sair.'):'Consulte novamente com internet'}</small></div><select id="weather-city" aria-label="Cidade da previsão"><option ${S.weatherCity==='Maringá'?'selected':''}>Maringá</option><option ${S.weatherCity==='Sarandi'?'selected':''}>Sarandi</option></select></div>`;}
function greeting(){const hour=Number(new Intl.DateTimeFormat('pt-BR',{hour:'numeric',hour12:false,timeZone:'America/Sao_Paulo'}).format(new Date()));return hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';}
function pageHead(title,subtitle){return `<div class="page-head"><div><span class="upper">${greeting()}, ${esc(S.user.nome.split(' ')[0])}</span><h1>${title}</h1><p>${subtitle}</p></div>${weather()}</div>`;}
function statusPill(run){return `<span class="pill ${run.gps_recente?'green':'orange'}"><span class="dot"></span>${run.gps_recente?'GPS recente':'Sem GPS recente'}</span>`;}
function empty(title,description,ico='bus',button=''){return `<div class="empty"><div class="empty-icon">${icon(ico)}</div><h3>${title}</h3><p>${description}</p>${button}</div>`;}
function runCard(run){return `<article class="trip-card"><div class="trip-top"><span class="line-code">${esc(run.linha?.code||'—')}</span><div><h3>${esc(run.linha?.name||'Viagem')}</h3><p>${esc(run.linha?.city)} • ${esc(run.sentido)}</p></div></div><div class="row between" style="margin-bottom:16px">${statusPill(run)}<span class="pill ${lotClass(run.lotacao)}">${esc(labelLot(run.lotacao))}</span></div><div class="trip-meta"><div><span>Motorista autodeclarado</span><strong>${esc(run.motorista)}</strong></div><div><span>Veículo informado</span><strong>${esc(run.veiculo)}</strong></div><div><span>Avaliação no app</span><strong>${run.nota_media_motorista===null?'Sem avaliações':esc(run.nota_media_motorista)+' ★'} ${run.total_avaliacoes_motorista?`<small class="muted">(${run.total_avaliacoes_motorista})</small>`:''}</strong></div><div><span>GPS compartilhado</span><strong>${run.gps_recente?'Atualizado às '+esc(when(run.gps_em).split(' ')[1]||when(run.gps_em)):'Aguardando permissão/sinal'}</strong></div></div><div class="row actions"><button class="btn secondary small" data-action="view-run" data-id="${esc(run.id)}">${icon('map')} Ver no mapa</button>${S.user.perfil==='passageiro'?`<button class="btn small" data-action="board-modal" data-id="${esc(run.id)}">Registrar embarque ${icon('arrow')}</button>`:''}</div></article>`;}
function selectedRun(){if(S.user?.perfil==='motorista'&&S.me?.viagem)return S.me.viagem;if(S.tab==='viagem')return S.me?.embarque?.viagem||S.me?.ultimo_embarque?.viagem||null;return S.runs.find(r=>r.id===S.selectedRun)||S.me?.embarque?.viagem||null;}
function mapCard(mode='explorar',large=false){return `<section class="card map-card ${large?'large':''}"><div class="map-card-head"><div><h3>${mode==='planejar'?'Escolha os pontos no mapa':mode==='viagem'?'Seu caminho no mapa':'Maringá e Sarandi no mapa'}</h3><small>${mode==='planejar'?'Clique em até 8 pontos, na ordem do percurso':'Mapa real • OpenStreetMap'}</small></div><span class="pill green">${icon('map')} MAPA</span></div><div id="map" role="region" aria-label="Mapa interativo de transporte"></div><p class="map-notice" id="map-notice">O mapa precisa de internet. Marcadores não representam veículos oficiais da operadora.</p><div class="map-tools"><button class="btn secondary small" data-action="locate">${icon('gps')} Minha localização</button><button class="btn secondary small" data-action="fit-map">${icon('map')} Ajustar mapa</button>${mode==='planejar'?'<button class="btn secondary small" data-action="clear-points">Limpar pontos</button>':''}</div><div class="map-footer"><a href="https://www.nahoramaringa.com.br/pesquisa-por-linhas/" target="_blank" rel="noopener noreferrer">Consultar horários e linhas no portal Na Hora Maringá</a><br>${mode==='planejar'?'<strong>Pontos escolhidos por você.</strong> O percurso viário usa OSRM, perfil de automóvel. Não é linha oficial nem considera todas as restrições de ônibus.':selectedRun()?.percurso?.geometria?'<strong>Percurso viário de referência.</strong> Foi escolhido pelo motorista; não é itinerário oficial de ônibus.':'<strong>Itinerário oficial não carregado.</strong> Não desenhamos uma linha aproximada como se fosse da operadora.'}</div></section>`;}
function lineCards(){const q=S.query.toLocaleLowerCase('pt-BR');const list=S.lines.filter(l=>(S.filter==='Todas'||l.city===S.filter)&&(!S.onlyFavorites||S.favorites.includes(l.id))&&[l.code,l.name,l.city,l.regions,...(l.routeNotes||[])].join(' ').toLocaleLowerCase('pt-BR').includes(q));return list.length?list.map(l=>{const runs=S.runs.filter(r=>r.linha_id===l.id);return `<article class="line-card"><div class="line-main"><span class="line-code">${esc(l.code)}</span><div><h3>${esc(l.name)}</h3><p>${esc(l.city)} • Catálogo secundário</p></div><button class="icon-btn ${S.favorites.includes(l.id)?'selected':''}" data-action="favorite" data-id="${esc(l.id)}" aria-label="${S.favorites.includes(l.id)?'Remover dos':'Adicionar aos'} favoritos">${icon('heart')}</button></div><div class="line-bottom"><span>${runs.length?runs.length+' viagem(ns) declarada(s) no app':'Sem viagem compartilhada agora'}</span><button data-action="line-detail" data-id="${esc(l.id)}">Ver linha ${icon('arrow')}</button></div></article>`;}).join(''):empty('Nenhuma linha encontrada','Tente outro nome, código ou filtro.','search');}
function explore(){if(S.user.perfil==='motorista')return driverHome();return `${pageHead('Para onde vamos hoje?','Encontre sua linha e acompanhe viagens compartilhadas no aplicativo.')}<div class="stat-grid"><div class="stat"><span class="stat-icon">${icon('route')}</span><div><label>Linhas no catálogo</label><strong>${S.lines.length}</strong><small>fontes secundárias</small></div></div><div class="stat"><span class="stat-icon">${icon('bus')}</span><div><label>Viagens compartilhadas</label><strong>${S.runs.length}</strong><small>declaradas por usuários</small></div></div><div class="stat"><span class="stat-icon">${icon('gps')}</span><div><label>Com GPS recente</label><strong>${S.runs.filter(r=>r.gps_recente).length}</strong><small>últimos 90 segundos</small></div></div></div><div class="explore-grid"><section class="card"><div class="card-head"><div><h2>Encontre sua linha</h2><p>Busque por número, destino ou região.</p></div>${icon('bus')}</div><label class="search">${icon('search')}<input id="line-search" value="${esc(S.query)}" placeholder="Ex.: 007, Interbairros, Centro…" aria-label="Buscar linha"></label><div class="filters">${['Todas','Maringá','Sarandi'].map(c=>`<button class="filter ${S.filter===c?'active':''}" data-action="filter" data-value="${esc(c)}">${esc(c)}</button>`).join('')}<button class="filter ${S.onlyFavorites?'active':''}" data-action="favorites">♥ Favoritas</button></div><div id="line-list" class="line-list">${lineCards()}</div><p class="small muted" style="font-size:10px;margin:15px 0 0">Catálogo recebido de fonte secundária, sem reconfirmação atual nesta versão. Confira horários e itinerário com a operadora.</p></section><div class="stack">${mapCard()}<section class="card"><div class="card-head"><div><h2>Viagens disponíveis</h2><p>Contas de motorista deste ambiente, sem vínculo oficial.</p></div><button class="icon-btn" data-action="refresh" aria-label="Atualizar viagens">${icon('refresh')}</button></div>${S.runs.length?S.runs.slice(0,5).map(runCard).join(''):empty('Nenhuma viagem compartilhada','Uma conta de motorista pode iniciar uma viagem. A localização aparece somente com consentimento e GPS recente.','bus')}</section></div></div>`;}
function driverHome(){const v=S.me?.viagem;return `${pageHead('Pronto para o próximo caminho?','Planeje com o veículo parado e compartilhe sua viagem quando desejar.')}<div class="stat-grid"><div class="stat"><span class="stat-icon">${icon('bus')}</span><div><label>Minha viagem</label><strong style="font-size:18px">${v?'Em andamento':'Não iniciada'}</strong><small>${v?esc(v.linha?.code)+' • '+esc(v.veiculo):'Você controla o início e o fim'}</small></div></div><div class="stat"><span class="stat-icon">${icon('users')}</span><div><label>Embarques ativos no app</label><strong>${v?.embarcados_no_app||0}</strong><small>não é lotação física</small></div></div><div class="stat"><span class="stat-icon">${icon('star')}</span><div><label>Avaliação desta conta</label><strong>${S.me?.resumo_motorista?.nota_media??'—'}</strong><small>${S.me?.resumo_motorista?.total_avaliacoes||0} avaliação(ões)</small></div></div></div><div class="explore-grid"><section class="card">${v?`<div class="card-head"><h2>Sua viagem está aberta</h2>${statusPill(v)}</div>${runCard(v)}<button class="btn full" data-action="nav" data-tab="viagem">Abrir painel da viagem ${icon('arrow')}</button>`:`<div class="card-head"><div><h2>Iniciar uma viagem</h2><p>Perfil de motorista autodeclarado, não verificado pela operadora.</p></div>${icon('flag')}</div><form id="start-run-form" class="form"><label class="field">Linha do catálogo<select name="linha_id" required>${S.lines.map(l=>`<option value="${esc(l.id)}" ${S.planLine===l.id?'selected':''}>${esc(l.code)} · ${esc(l.name)} — ${esc(l.city)}</option>`).join('')}</select></label><div class="grid2"><label class="field">Prefixo do veículo<input name="veiculo" maxlength="20" required placeholder="Ex.: DEMO-01"></label><label class="field">Sentido informado<input name="sentido" maxlength="100" minlength="2" required placeholder="Ex.: Ida ao terminal"></label></div><div class="notice">${icon('map')}<span>${S.plan?'Percurso escolhido salvo. Ele será vinculado à viagem.':'Sem itinerário oficial carregado. Você pode planejar pontos e uma rota viária de referência.'}</span></div><button type="button" class="btn secondary full" data-action="nav" data-tab="planejar">${icon('map')} ${S.plan?'Revisar percurso':'Planejar pontos no mapa'}</button><button class="btn full" type="submit">Iniciar viagem de demonstração ${icon('arrow')}</button></form>`}</section><div class="stack">${mapCard()}<section class="card"><h3>Uma experiência transparente</h3><div class="mini-row"><span class="mini-icon">${icon('gps')}</span><div><h3>Localização sob seu controle</h3><p>O GPS só é compartilhado depois da sua permissão.</p></div></div><div class="mini-row"><span class="mini-icon">${icon('route')}</span><div><h3>Percurso de referência</h3><p>OSRM consulta vias reais, mas não substitui a linha da operadora.</p></div></div><div class="mini-row"><span class="mini-icon">${icon('star')}</span><div><h3>Feedback de cada experiência</h3><p>As avaliações ficam vinculadas a um embarque declarado.</p></div></div></section></div></div>`;}
function planPage(){return `${pageHead('Desenhe seu próximo percurso.','Escolha no mapa os pontos por onde deseja passar, na ordem.')}<div class="explore-grid"><section class="card"><div class="card-head"><div><h2>Pontos do percurso</h2><p>De 2 a 8 pontos escolhidos por você.</p></div><span class="pill">${S.points.length}/8</span></div><div class="notice warning" style="margin-bottom:18px">${icon('info')}<span>Este planejador é viário. Não identifica pontos oficiais nem garante que um ônibus possa trafegar por todas as vias calculadas.</span></div><div class="plan-list">${S.points.map((p,i)=>`<div class="plan-point"><span>${i+1}</span><div style="flex:1;min-width:0"><input data-point-name="${i}" value="${esc(p.nome)}" maxlength="80" aria-label="Nome do ponto ${i+1}"><small>${p.latitude.toFixed(5)}, ${p.longitude.toFixed(5)}</small></div><button data-action="remove-point" data-index="${i}" aria-label="Remover ponto ${i+1}">${icon('close')}</button></div>`).join('')||empty('Clique no mapa para começar','O primeiro ponto será o início. O último será o destino.','pin')}</div><div class="stack" style="margin-top:20px"><button class="btn full" data-action="calculate-route" ${S.points.length<2?'disabled':''}>${icon('route')} Calcular percurso nas vias</button><button class="btn secondary full" data-action="save-points" ${S.points.length<2?'disabled':''}>Salvar somente pontos, sem traçar rota</button>${S.plan?`<div class="notice success">${icon('check')}<span>Percurso salvo. ${S.plan.distancia_m===null?'Sem linha viária: apenas os pontos escolhidos.':(S.plan.distancia_m/1000).toFixed(1)+' km de referência viária.'}</span></div><button class="btn dark full" data-action="nav" data-tab="explorar">Voltar para iniciar a viagem ${icon('arrow')}</button>`:''}</div></section><div class="stack">${mapCard('planejar',true)}${S.plan?.instrucoes?.length?`<section class="card"><h3>Referência de navegação</h3><p class="small muted">Sem trânsito ao vivo ou restrições específicas de ônibus.</p><ol class="instructions">${S.plan.instrucoes.slice(0,40).map(s=>`<li><div>${esc(turnText(s))}<small>${Math.round(s.distancia_m)} m${s.via?' • '+esc(s.via):''}</small></div></li>`).join('')}</ol></section>`:''}</div></div>`;}
function turnText(s){const type={depart:'Inicie o percurso',arrive:'Chegada ao ponto',turn:'Vire',continue:'Continue',merge:'Entre na via',fork:'Mantenha-se na bifurcação',roundabout:'Siga pela rotatória','new name':'Continue pela via','end of road':'No final da via, siga'}[s.tipo]||'Siga o percurso';const dir={left:'à esquerda',right:'à direita','slight left':'levemente à esquerda','slight right':'levemente à direita','sharp left':'à esquerda','sharp right':'à direita',straight:'em frente',uturn:'fazendo o retorno'}[s.direcao]||'';return type+' '+dir;}
function pointName(run,index,fallback){return run?.percurso?.pontos?.[index]?.nome||fallback;}
function tripPage(){if(S.user.perfil==='motorista')return driverTrip();const b=S.me?.embarque||S.me?.ultimo_embarque;const v=b?.viagem;return `${pageHead('Sua viagem, em um só lugar.','Registre seu embarque, acompanhe as informações e conte como foi.')}<div class="explore-grid"><section class="card">${!b?empty('Você ainda não embarcou','Escolha uma viagem compartilhada para registrar o embarque. Isso não valida um bilhete nem cobra passagem.','route','<button class="btn" data-action="nav" data-tab="explorar">Explorar viagens</button>'):`<div class="card-head"><div><span class="pill ${b.ativo?'green':'purple'}">${b.ativo?'Embarque ativo':'Desembarque registrado'}</span><h2 style="margin-top:13px">${esc(v.linha?.code)} · ${esc(v.linha?.name)}</h2><p>${esc(v.motorista)} • ${esc(v.veiculo)}</p></div>${icon('bus')}</div><div class="timeline"><div class="timeline-point"><span></span><div><small>Embarque escolhido</small><strong>${esc(pointName(v,b.ponto_embarque,'Ponto não informado'))}</strong></div></div><div class="timeline-point"><span></span><div><small>Destino escolhido</small><strong>${esc(pointName(v,b.ponto_desembarque,'Destino não informado'))}</strong></div></div></div><div class="row" style="margin-bottom:18px">${statusPill(v)}<span class="pill ${lotClass(v.lotacao)}">${esc(labelLot(v.lotacao))}</span></div><p class="small muted">Previsão de chegada indisponível: não há integração oficial com o itinerário e a frota. ${v.gps_recente?'Posição compartilhada em '+esc(when(v.gps_em))+'.':''}</p>${b.ativo?`<div class="stack"><div><h3>Como está a lotação?</h3><div class="occupancy">${LOTACOES_HTML('report-occupancy',null,b.id)}</div><p class="small muted" style="font-size:10px;margin:9px 0">Seu relato fica disponível por até 15 minutos.</p></div>${v.percurso?.pontos?.[b.ponto_desembarque]?`<label class="check"><input type="checkbox" id="arrival-alert" ${S.alertArrival?'checked':''}><span>Avisar nesta página quando meu GPS estiver próximo do destino escolhido.</span></label>`:''}<button class="btn full" data-action="disembark" data-id="${esc(b.id)}">Registrar desembarque ${icon('arrow')}</button></div>`:b.avaliacao?`<div class="notice success">${icon('star')}<div><strong>Avaliação registrada: ${b.avaliacao.nota}/5</strong><p>${esc(b.avaliacao.descricao)}</p></div></div>`:`<button class="btn full" data-action="review-modal" data-id="${esc(b.id)}">${icon('star')} Avaliar esta viagem</button>`}<div class="notice" style="margin-top:18px">${icon('info')}<span>Embarque autodeclarado no app. Não substitui validação de passe ou cobrança da operadora. Alertas exigem GPS, permissão e esta página aberta.</span></div>`}</section><div class="stack">${mapCard('viagem',true)}${v?.percurso?.pontos?`<section class="card"><h3>Pontos informados pelo motorista</h3><div class="timeline">${v.percurso.pontos.map((p,i)=>`<div class="timeline-point"><span></span><div><small>Ponto ${i+1} • não oficial</small><strong>${esc(p.nome)}</strong></div></div>`).join('')}</div></section>`:''}</div></div>`;}
function LOTACOES_HTML(actionName,active,id=''){return ['vazio','medio','cheio','superlotado'].map(v=>`<button type="button" data-action="${actionName}" data-value="${v}" data-id="${esc(id)}" class="${active===v?'active':''}">${esc(labelLot(v))}</button>`).join('');}
function driverTrip(){const v=S.me?.viagem;return `${pageHead('No controle da sua viagem.','Compartilhe sua localização somente quando desejar.')}<div class="explore-grid"><section class="card">${!v?empty('Nenhuma viagem iniciada','Planeje o percurso e inicie uma viagem pelo seu painel.','bus','<button class="btn" data-action="nav" data-tab="explorar">Abrir meu painel</button>'):`<div class="card-head"><div><span class="pill green">Viagem em andamento</span><h2 style="margin-top:13px">${esc(v.linha?.code)} · ${esc(v.linha?.name)}</h2><p>${esc(v.sentido)} • ${esc(v.veiculo)}</p></div>${icon('bus')}</div><div class="row between" style="margin-bottom:20px">${statusPill(v)}<span class="small muted">${v.embarcados_no_app} embarque(s) ativo(s) no app</span></div><div class="stack"><div class="notice ${S.gpsSharing?'success':''}">${icon('gps')}<span>${S.gpsSharing?'Compartilhamento solicitado. A posição só aparece para passageiros quando o servidor receber sinal recente e preciso.':'Seu GPS não está sendo enviado por esta página. Você escolhe quando compartilhar.'}</span></div>${S.gpsSharing?'<button class="btn secondary full" data-action="stop-gps">Parar de compartilhar GPS</button>':`<label class="check"><input type="checkbox" id="gps-consent"><span>Quero compartilhar minha localização nesta viagem com as contas de passageiros deste servidor, enquanto esta página estiver aberta.</span></label><button class="btn full" data-action="start-gps">${icon('gps')} Compartilhar meu GPS</button>`}<div><h3>Informe a lotação</h3><div class="occupancy">${LOTACOES_HTML('driver-occupancy',v.lotacao,v.id)}</div><p class="small muted" style="font-size:10px;margin:8px 0">Informação declarada, não medição automática.</p></div><button class="btn danger full" data-action="end-run" data-id="${esc(v.id)}">Encerrar viagem</button></div><div class="notice warning" style="margin-top:18px">${icon('info')}<span>Planeje e ajuste o app com o veículo parado. O percurso de referência não substitui o itinerário da operadora nem navegação específica para ônibus.</span></div>`}</section><div class="stack">${mapCard('viagem',true)}${v?.percurso?.instrucoes?.length?`<section class="card"><h3>Próximas referências do percurso</h3><p class="small muted">Lista do percurso planejado. Não há detecção automática da próxima conversão ou trânsito ao vivo.</p><ol class="instructions">${v.percurso.instrucoes.slice(0,35).map(s=>`<li><div>${esc(turnText(s))}<small>${Math.round(s.distancia_m)} m ${esc(s.via)}</small></div></li>`).join('')}</ol></section>`:''}</div></div>`;}
function walletPage(){const w=S.wallet;const tariff=S.config?.tarifa;return `${pageHead('Seu passe, com mais clareza.','Explore a experiência de carteira e vale-transporte em demonstração.')}<div class="wallet-grid"><div class="stack"><section class="wallet-card"><div><div class="row between"><span class="logo-text">TRANS<span style="color:#44dfb9">URBAN</span></span>${icon('wallet')}</div><span class="upper">Saldo de demonstração • não é dinheiro real</span><div class="balance">${w?money(w.saldo_centavos):'—'}</div><div class="card-bottom"><span>${esc(S.user.nome)}</span><span>AMBIENTE DE TESTE</span></div></div></section><div class="row actions"><button class="btn" data-action="topup-modal">${icon('plus')} Simular recarga</button><button class="btn secondary" data-action="vt-modal">${icon('company')} Simular VT</button></div><div class="notice warning">${icon('info')}<span>Sem cobrança real, PIX, integração bancária ou crédito da operadora. Este saldo não permite embarcar em ônibus.</span></div><section class="card"><h3>Tarifa e equivalência de demonstração</h3><div class="mini-row"><span class="mini-icon">${icon('bus')}</span><div><h3>Maringá · referência 2026</h3><p>${tariff?.verificada?money(tariff.valor_centavos)+' • integral urbana': 'Tarifa ainda não verificada'}</p></div></div><p class="small muted">${tariff?.verificada?'Referência publicada pela Prefeitura em 10/07/2026, válida desde 12/07/2026. Somente Maringá urbana; não aplicar automaticamente a Sarandi ou a benefícios.':'Preço aguardando fonte confirmada.'}</p>${w?.equivalencia_demonstracao?`<div class="notice" style="margin:14px 0">${icon('info')}<span>Seu saldo de teste equivale matematicamente a <strong>${w.equivalencia_demonstracao.quantidade} tarifa(s) integral(is)</strong>, com ${money(w.equivalencia_demonstracao.resto_centavos)} restantes. Não são bilhetes nem passam na catraca.</span></div>`:''}<p class="small muted">A aceitação de cartão, PIX, parcelamento e VT reais depende da operadora e do provedor contratado.</p><a class="source-link" href="${esc(tariff?.fonte_url||'https://www.tccc.com.br/')}" target="_blank" rel="noopener noreferrer">${tariff?.verificada?'Consultar notícia oficial da Prefeitura':'Conferir com a operadora'} ${icon('arrow')}</a></section></div><section class="card"><div class="card-head"><div><h2>Seu extrato de demonstração</h2><p>Créditos de teste registrados neste servidor.</p></div>${icon('clock')}</div><div class="row" style="margin-bottom:18px"><span class="pill purple">VT de teste: ${w?money(w.credito_vt_centavos):'—'}</span><span class="pill">Sem validação de bilhete</span></div>${!w?'<p class="small muted">Carregando extrato…</p>':w.lancamentos?.length?w.lancamentos.map(t=>`<div class="mini-row"><span class="mini-icon">${icon(t.tipo==='vt_demo'?'company':'wallet')}</span><div><h3>${t.tipo==='vt_demo'?'Vale-transporte simulado':'Recarga simulada'}</h3><p>${t.origem?esc(t.origem)+' • empresa não verificada':esc({pix:'PIX demonstrativo',credito:'Crédito demonstrativo',debito:'Débito demonstrativo'}[t.metodo]||t.metodo)}${t.parcelas>1?' • '+t.parcelas+' parcelas ilustrativas':''}<br>${esc(when(t.criado_em))}</p></div><strong class="value" style="color:var(--green)">+ ${money(t.valor_centavos)}</strong></div>`).join(''):empty('Seu extrato começa aqui','Simule uma recarga ou um crédito de vale-transporte para explorar a experiência. Nenhum valor real será movimentado.','wallet')}</section></div>`;}
function reviewsPage(){return `${pageHead(S.user.perfil==='motorista'?'Cada experiência importa.':'Suas experiências registradas.',S.user.perfil==='motorista'?'Veja as avaliações recebidas nos embarques vinculados às suas viagens.':'Você pode avaliar depois de registrar o desembarque.')}<section class="card"><div class="card-head"><div><h2>${S.user.perfil==='motorista'?'Avaliações recebidas':'Minhas avaliações'}</h2><p>De 1 a 5 estrelas, descrição e relato de lotação.</p></div>${icon('star')}</div>${S.reviews.length?S.reviews.map(r=>`<article class="review"><div class="row between"><span class="rating" aria-label="${r.nota} de 5 estrelas">${'★'.repeat(r.nota)}${'☆'.repeat(5-r.nota)}</span><span class="pill ${lotClass(r.lotacao)}">${esc(labelLot(r.lotacao))}</span></div><p>${esc(r.descricao)}</p><div class="review-footer"><span>Embarque declarado no app • sem nome público do passageiro</span><span>${esc(when(r.criada_em))}</span></div></article>`).join(''):empty('Ainda não há avaliações','Depois de uma viagem, o passageiro pode registrar como foi a experiência. Não criamos notas ou comentários fictícios.','star')}</section>`;}
function aboutPage(){return `${pageHead('Feito para aproximar pessoas.','Conheça o que está conectado e o que ainda é demonstração.')}<div class="info-grid"><section class="card"><h2>O que funciona neste servidor</h2><ul><li>Cadastro e login com perfis de passageiro e motorista.</li><li>Consulta do catálogo, favoritos e viagens autodeclaradas.</li><li>Planejamento de pontos e consulta de vias ao OSRM, quando disponível.</li><li>Compartilhamento voluntário de GPS recente, embarque e desembarque.</li><li>Avaliação de 1 a 5 estrelas, descrição e quatro níveis de lotação.</li><li>Carteira e VT de demonstração com extrato persistido no banco.</li></ul><h3>Teste entre passageiro e motorista</h3><p>Abra uma conta na janela normal e outra em janela anônima. Duas abas comuns compartilham a mesma sessão. As contas e seus registros ficam no banco deste servidor.</p><p>O GPS depende de permissão, precisão, página aberta e contexto seguro. No notebook, localhost é aceito pelo navegador. Para outros dispositivos, é necessário HTTPS configurado; não prometemos GPS em HTTP da rede local.</p></section><section class="card"><h2>Fontes e limites</h2><p>O catálogo recebido do pacote anterior usa o Ônibus Online, fonte secundária. A consulta declarada é de 16/10/2026 e não foi reconfirmada nesta sessão. Não há itinerário oficial validado de Maringá/Sarandi nesta versão.</p><p>O mapa é do OpenStreetMap. Percursos consultados ao OSRM são rotas viárias de automóvel, não linhas oficiais nem navegação específica para ônibus. O clima, quando disponível, vem do Open-Meteo com horário de consulta.</p><p>A tarifa de Maringá em 2026 ainda não foi verificada. Recargas, parcelamento até 12 vezes e depósitos de VT são exclusivamente demonstrativos. Não coletamos número de cartão ou CVV e não geramos cobrança PIX.</p><div class="stack"><a class="source-link" href="https://www.nahoramaringa.com.br/" target="_blank" rel="noopener noreferrer">Na Hora Maringá ${icon('arrow')}</a><a class="source-link" href="https://www.tccc.com.br/" target="_blank" rel="noopener noreferrer">Operadora TCCC ${icon('arrow')}</a><a class="source-link" href="https://onibus.online/pr/maringa/" target="_blank" rel="noopener noreferrer">Catálogo secundário ${icon('arrow')}</a><a class="source-link" href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo ${icon('arrow')}</a><a class="source-link" href="/docs" target="_blank" rel="noopener">API Python e avaliação ${icon('arrow')}</a></div></section></div>`;}
function render(){if(map){try{S.mapCenter=map.getCenter();S.mapZoom=map.getZoom();map.stop();map.remove();}catch{}map=null;}if(!S.user){app.innerHTML=auth();return;}const items=navItems(),current=items.find(i=>i[0]===S.tab)||items[0];const views={explorar:explore,planejar:planPage,viagem:tripPage,carteira:walletPage,avaliacoes:reviewsPage,sobre:aboutPage};app.innerHTML=`<div class="shell"><aside class="sidebar">${logo()}<div><div class="sidebar-label">${S.user.perfil==='motorista'?'ÁREA DO MOTORISTA':'SUA MOBILIDADE'}</div><nav class="nav" aria-label="Menu principal">${items.map(([tab,ico,label])=>`<button data-action="nav" data-tab="${tab}" class="${S.tab===tab?'active':''}">${icon(ico)} ${label}</button>`).join('')}</nav></div><div class="sidebar-bottom"><div class="sidebar-demo">${icon('info')} <strong>Projeto independente</strong><br>Demonstração funcional. Sem operação oficial ou pagamentos reais.</div><button class="profile-btn" data-action="profile"><span class="avatar">${esc(initials())}</span><span><strong>${esc(S.user.nome)}</strong><small>${S.user.perfil==='motorista'?'Motorista autodeclarado':'Passageiro'}</small></span></button></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">TRANSURBAN <span style="padding:0 8px">/</span> <b>${current[2]}</b></span><div class="topbar-actions"><span class="topbar-date">${new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',timeZone:'America/Sao_Paulo'}).format(new Date())}</span><span class="pill ${S.connected?'green':'orange'}"><span class="dot"></span>${S.connected?'Servidor conectado':'Sem conexão'}</span><button class="icon-btn" data-action="profile" aria-label="Minha conta"><span style="font-size:12px;font-weight:800">${esc(initials())}</span></button></div></header><main id="main" class="content"><div class="demo-strip">${icon('info')} Ambiente de demonstração • viagens autodeclaradas • sem pagamentos reais</div>${(views[S.tab]||explore)()}<footer class="footer"><span>TRANSURBAN · Mobilidade com contexto.</span><span>Projeto acadêmico independente · <a href="/docs" target="_blank" rel="noopener">API Python</a></span></footer></main></div><nav class="mobile-nav" aria-label="Menu móvel">${items.map(([tab,ico,label])=>`<button data-action="nav" data-tab="${tab}" class="${S.tab===tab?'active':''}">${icon(ico)}<span>${label}</span></button>`).join('')}</nav></div>`;initMap();}
function markerIcon(type,number){return L.divIcon({className:'',html:`<div class="map-pin ${type||''}">${number??'●'}</div>`,iconSize:[31,31],iconAnchor:[15,15]});}
function popup(title,description){const box=document.createElement('div');const b=document.createElement('strong');b.textContent=title;box.append(b);if(description){const p=document.createElement('div');p.textContent=description;box.append(p);}return box;}
function initMap(){if(!$('#map')||!window.L)return;const planning=S.tab==='planejar';const v=selectedRun();const center=S.mapCenter?[S.mapCenter.lat,S.mapCenter.lng]:S.filter==='Sarandi'?[-23.4441,-51.8767]:[-23.425,-51.925];map=L.map('map',{zoomControl:true,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView(center,S.mapZoom||13);let loaded=0,failures=0;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors',maxZoom:19}).on('tileload',()=>{loaded++;const el=$('#map-notice');if(el&&loaded===1)el.textContent='Mapa real • OpenStreetMap. Percurso oficial de ônibus não validado.';}).on('tileerror',()=>{failures++;const el=$('#map-notice');if(el&&!loaded&&failures>=2)el.textContent='Sem acesso às imagens do mapa. Confira a conexão com a internet.';}).addTo(map);mapLayers=L.featureGroup().addTo(map);const plan=planning?S.plan:v?.percurso;const points=planning?S.points:plan?.pontos||[];if(plan?.geometria){L.geoJSON(plan.geometria,{style:{color:'#fff',weight:10,opacity:.95}}).addTo(mapLayers);L.geoJSON(plan.geometria,{style:{color:'#009b7c',weight:6,opacity:.95}}).addTo(mapLayers);}points.forEach((p,i)=>L.marker([p.latitude,p.longitude],{icon:markerIcon(i===points.length-1?'destination':'',i+1)}).bindPopup(popup(p.nome,'Ponto escolhido pelo motorista; não oficial.')).addTo(mapLayers));const runs=v?[v]:S.runs;for(const r of runs){if(r.gps_recente&&Number.isFinite(r.latitude)&&Number.isFinite(r.longitude)){L.marker([r.latitude,r.longitude],{icon:markerIcon('bus',icon('bus'))}).bindPopup(popup((r.linha?.code||'')+' · '+r.veiculo,'GPS voluntário recente. '+r.motorista)).addTo(mapLayers);}}if(S.myLocation){L.marker([S.myLocation.lat,S.myLocation.lng],{icon:markerIcon('me','●')}).bindPopup(popup('Sua localização','Esta localização de passageiro não é enviada ao servidor.')).addTo(mapLayers);}if(planning){map.on('click',e=>{if(S.points.length>=8){toast('O planejador aceita até 8 pontos.');return;}S.points.push({nome:'Ponto '+(S.points.length+1),latitude:e.latlng.lat,longitude:e.latlng.lng});S.plan=null;requestAnimationFrame(()=>render());});}if(!S.mapCenter&&mapLayers.getLayers().length)fitMap();setTimeout(()=>map?.invalidateSize(),30);}
function fitMap(){if(!map||!mapLayers)return;try{const b=mapLayers.getBounds();if(b.isValid())map.fitBounds(b.pad(.2),{maxZoom:16});}catch{}}
async function loadWeather(){S.weatherLoading=true;const city=S.weatherCity;try{const w=await api('clima?cidade='+encodeURIComponent(city));if(S.weatherCity===city)S.weather=w;}catch{if(S.weatherCity===city)S.weather=null;}finally{S.weatherLoading=false;if(S.user){const el=$('.weather');if(el)el.outerHTML=weather();}}}
async function refresh(force=false){if(!S.user||polling)return;polling=true;try{const [me,runs]=await Promise.all([api('me'),api('viagens')]);S.me=me;S.user=me.conta;S.runs=runs.viagens;if(S.tab==='carteira')S.wallet=await api('carteira');if(S.tab==='avaliacoes')S.reviews=(await api('minhas-avaliacoes')).avaliacoes;const typing=Boolean(document.querySelector('input:focus,textarea:focus,select:focus'));if(force||(!typing&&!modal.open&&S.tab!=='planejar'&&!$('#start-run-form')))render();}catch(e){if(e.status===401){stopWatches();S.user=null;S.me=null;render();}else if(force)toast(e.message);}finally{polling=false;}}
async function navigate(tab){if(!navItems().some(x=>x[0]===tab))return;S.tab=tab;S.mapCenter=null;S.mapZoom=13;await refresh(true);window.scrollTo({top:0,behavior:'smooth'});}
function openModal(body){modal.innerHTML=`<button class="modal-close" data-action="close-modal" aria-label="Fechar">${icon('close')}</button>${body}`;if(!modal.open)modal.showModal();setTimeout(()=>modal.querySelector('input,select,textarea,button[type=submit]')?.focus(),50);}
function closeModal(){modal.close();modal.innerHTML='';}
function lineDetail(id){const l=S.lines.find(x=>x.id===id);if(!l)return;const runs=S.runs.filter(r=>r.linha_id===id);openModal(`<div class="modal-icon">${icon('bus')}</div><span class="pill green">${esc(l.city)} · ${esc(l.code)}</span><h2 style="margin-top:14px">${esc(l.name)}</h2><p>${esc(l.operator)}</p><h3>Descrições recebidas no catálogo</h3><ul class="line-detail-notes">${(l.routeNotes||[]).map(n=>`<li>${esc(n)}</li>`).join('')||'<li>Sem descrição disponível.</li>'}</ul><a class="btn secondary full" href="${esc(l.source)}" target="_blank" rel="noopener noreferrer">Consultar fonte secundária ${icon('arrow')}</a><p class="small muted" style="margin-top:12px">Consulta declarada ${esc(l.checkedAt)}. Não reconfirmada nesta versão. Horários e itinerário atuais precisam ser conferidos com a operadora.</p><hr class="dialog-divider"><h3>Viagens compartilhadas no app</h3>${runs.length?runs.map(runCard).join(''):empty('Sem viagem compartilhada','Nenhum motorista deste ambiente iniciou uma viagem nessa linha.','bus')}`);}
function boardModal(id){const v=S.runs.find(r=>r.id===id);if(!v)return;const points=v.percurso?.pontos||[];openModal(`<div class="modal-icon">${icon('bus')}</div><h2>Vamos nessa?</h2><p>${esc(v.linha?.code)} · ${esc(v.linha?.name)}<br>${esc(v.motorista)} • ${esc(v.veiculo)}</p><form id="board-form" class="form" data-id="${esc(id)}">${points.length>=2?`<label class="field">Onde você embarca?<select name="origem">${points.slice(0,-1).map((p,i)=>`<option value="${i}">${esc(p.nome)}</option>`).join('')}</select></label><label class="field">Onde pretende desembarcar?<select name="destino">${points.map((p,i)=>i?`<option value="${i}" ${i===points.length-1?'selected':''}>${esc(p.nome)}</option>`:'').join('')}</select></label><p class="field-note">Pontos informados pelo motorista, não validados como paradas oficiais.</p>`:'<div class="notice">Sem pontos de percurso informados. Você pode registrar o embarque e confirmar o desembarque manualmente.</div>'}<div class="notice warning">${icon('info')}<span>Este registro é autodeclarado. Não compra nem valida passagem. Viagem sem vínculo verificado com a operadora.</span></div><button class="btn full" type="submit">Confirmar meu embarque ${icon('arrow')}</button></form>`);}
function reviewModal(id){S.rating=0;S.reviewOccupancy='medio';openModal(`<div class="modal-icon">${icon('star')}</div><h2>Como foi sua viagem?</h2><p>Conte sobre condução, atendimento e conforto. Não inclua dados pessoais.</p><form id="review-form" class="form" data-id="${esc(id)}"><div><label class="field" style="margin-bottom:9px">Sua avaliação, de 1 a 5 estrelas</label><div class="stars">${[1,2,3,4,5].map(n=>`<button type="button" data-action="rate" data-value="${n}" aria-label="${n} ${n===1?'estrela':'estrelas'}">★</button>`).join('')}</div><span id="rating-label" class="field-note">Escolha uma nota.</span></div><div><label class="field" style="margin-bottom:9px">Como estava a lotação?</label><div class="occupancy" id="review-occupancy">${LOTACOES_HTML('review-occupancy','medio')}</div></div><label class="field">Sua experiência<textarea name="descricao" rows="4" minlength="3" maxlength="500" required placeholder="Conte como foi a viagem…"></textarea><span class="field-note">De 3 a 500 caracteres. O motorista pode ler sua descrição sem o nome público do passageiro.</span></label><button class="btn full" type="submit">Registrar avaliação ${icon('check')}</button></form>`);}
function topupModal(){S.paymentMethod='pix';S.paymentKey=crypto.randomUUID();openModal(`<div class="modal-icon">${icon('wallet')}</div><span class="pill orange">SOMENTE DEMONSTRAÇÃO</span><h2 style="margin-top:12px">Quanto deseja recarregar?</h2><p>Explore o fluxo sem movimentar dinheiro real.</p><form id="topup-form" class="form"><label class="field">Valor da recarga de teste (R$)<input type="number" name="valor" min="1" max="500" step="0.01" value="20.00" required></label><div class="quick-values">${[20,50,100].map(n=>`<button type="button" data-action="quick-value" data-value="${n}">${money(n*100)}</button>`).join('')}</div><div class="payment-options">${[['pix','pix','PIX'],['credito','card','Crédito'],['debito','card','Débito']].map(([value,ico,label])=>`<button type="button" data-action="payment-method" data-value="${value}" class="${value==='pix'?'active':''}">${icon(ico)}${label}</button>`).join('')}</div><label class="field" id="installments-field" hidden>Parcelas ilustrativas<select name="parcelas">${Array.from({length:12},(_,i)=>`<option value="${i+1}">${i+1} ${i?'parcelas':'parcela'}</option>`).join('')}</select><span class="field-note">Até 12x apenas neste protótipo. Condições, juros e aceitação reais dependem do provedor e da operadora.</span></label><div id="payment-note" class="notice warning">Não geramos cobrança ou código PIX real. Nenhum dinheiro será transferido.</div><button class="btn full" type="submit">Simular crédito na carteira ${icon('arrow')}</button></form>`);}
function vtModal(){S.paymentKey=crypto.randomUUID();openModal(`<div class="modal-icon">${icon('company')}</div><span class="pill orange">CRÉDITO DE TESTE</span><h2 style="margin-top:12px">Explore o vale-transporte</h2><p>Simule como um lançamento da empresa apareceria no extrato. Não há depósito empresarial real.</p><form id="vt-form" class="form"><label class="field">Nome ilustrativo da empresa<input name="empresa" required minlength="2" maxlength="100" placeholder="Empresa de demonstração"></label><label class="field">Valor de teste (R$)<input name="valor" type="number" min="1" max="500" step="0.01" value="100.00" required></label><div class="notice warning">Este lançamento é criado por você na demonstração. Não comprova vínculo, depósito ou crédito real de uma empresa.</div><button class="btn full" type="submit">Simular lançamento de VT ${icon('arrow')}</button></form>`);}
function profileModal(){openModal(`<div class="modal-icon">${icon('user')}</div><h2>${esc(S.user.nome)}</h2><p>${esc(S.user.email)}</p><div class="notice">${icon('info')}<span>${S.user.perfil==='motorista'?'Perfil de motorista autodeclarado; sem verificação pela operadora.':'Perfil de passageiro deste ambiente local.'}</span></div><p class="small muted" style="margin-top:17px">Para testar outro perfil simultaneamente, use uma janela anônima ou outro perfil do navegador. GPS não continua garantido em segundo plano.</p><button class="btn secondary full" data-action="logout">${icon('logout')} Sair da minha conta</button>`);}
async function locate(){if(!navigator.geolocation)throw Error('Este navegador não oferece geolocalização.');const p=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,()=>reject(Error('Localização não permitida ou indisponível. Confira a permissão do navegador.')),{enableHighAccuracy:true,timeout:12000,maximumAge:15000}));S.myLocation={lat:p.coords.latitude,lng:p.coords.longitude};S.mapCenter={lat:S.myLocation.lat,lng:S.myLocation.lng};S.mapZoom=15;render();toast('Sua localização foi usada somente neste navegador.');}
function stopWatches(){if(S.gpsWatch!==null)navigator.geolocation?.clearWatch(S.gpsWatch);if(S.passWatch!==null)navigator.geolocation?.clearWatch(S.passWatch);S.gpsWatch=null;S.passWatch=null;S.gpsSharing=false;S.alertArrival=false;}
async function shareGPS(){const v=S.me?.viagem;if(!v)throw Error('Inicie uma viagem primeiro.');if(!$('#gps-consent')?.checked)throw Error('Confirme o consentimento antes de compartilhar sua localização.');if(!navigator.geolocation)throw Error('Geolocalização indisponível neste navegador.');S.gpsSharing=true;S.lastGPS=0;S.gpsWatch=navigator.geolocation.watchPosition(async p=>{if(!S.gpsSharing)return;if(p.coords.accuracy>100){toast('Sinal impreciso. Aguardando localização com precisão de até 100 m.');return;}if(Date.now()-S.lastGPS<5000)return;S.lastGPS=Date.now();try{await api('viagens/'+v.id+'/gps',{latitude:p.coords.latitude,longitude:p.coords.longitude,precisao_m:p.coords.accuracy,velocidade_m_s:Number.isFinite(p.coords.speed)&&p.coords.speed>=0&&p.coords.speed<=50?p.coords.speed:null,consentimento:true});await refresh(true);}catch(e){toast(e.message);}},()=>{stopWatches();api('viagens/'+v.id+'/parar-gps',{}).catch(()=>{});toast('GPS não permitido ou sem sinal. Nenhuma posição foi inventada.');render();},{enableHighAccuracy:true,timeout:15000,maximumAge:5000});render();}
function distance(a,b){const r=x=>x*Math.PI/180,R=6371000;const da=r(b.latitude-a.latitude),dl=r(b.longitude-a.longitude);const h=Math.sin(da/2)**2+Math.cos(r(a.latitude))*Math.cos(r(b.latitude))*Math.sin(dl/2)**2;return 2*R*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
function arrival(enabled){if(S.passWatch!==null)navigator.geolocation.clearWatch(S.passWatch);S.passWatch=null;S.alertArrival=enabled;S.alertShown=false;if(!enabled)return;const b=S.me?.embarque,target=b?.viagem?.percurso?.pontos?.[b.ponto_desembarque];if(!target||!navigator.geolocation){S.alertArrival=false;toast('Escolha um destino e permita GPS para receber o aviso.');return;}S.passWatch=navigator.geolocation.watchPosition(p=>{if(p.coords.accuracy>100||S.alertShown)return;const meters=distance({latitude:p.coords.latitude,longitude:p.coords.longitude},target);if(meters<=150){S.alertShown=true;toast('Seu GPS está próximo do destino escolhido. Confira o local e registre o desembarque quando for adequado.');}},()=>{S.alertArrival=false;toast('Não foi possível acompanhar seu GPS para o aviso.');render();},{enableHighAccuracy:true,maximumAge:5000,timeout:15000});toast('Aviso ativado nesta página. Usa proximidade em linha reta, não garante chegada ao ponto oficial.');}
function cents(value){const normalized=String(value).replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(normalized))throw Error('Informe um valor com até duas casas decimais.');const [whole,decimal='']=normalized.split('.');const result=Number(whole)*100+Number(decimal.padEnd(2,'0'));if(!Number.isSafeInteger(result)||result<100||result>50000)throw Error('Use um valor de teste entre R$ 1 e R$ 500.');return result;}
document.addEventListener('input',e=>{if(e.target.id==='line-search'){S.query=e.target.value;$('#line-list').innerHTML=lineCards();}if(e.target.matches('[data-point-name]')){const i=Number(e.target.dataset.pointName);if(S.points[i]){S.points[i].nome=e.target.value;S.plan=null;}}});
document.addEventListener('change',e=>{if(e.target.id==='weather-city'){S.weatherCity=e.target.value;loadWeather();}if(e.target.id==='arrival-alert')arrival(e.target.checked);});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const act=button.dataset.action;const id=button.dataset.id;const value=button.dataset.value;const immediate={
 'auth-mode':()=>{S.authMode=value;render();},'auth-role':()=>{S.authRole=value;render();},
 'password':()=>{const input=button.previousElementSibling;input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'Mostrar':'Ocultar';},
 'reload':()=>location.reload(),'close-modal':closeModal,'profile':profileModal,'line-detail':()=>lineDetail(id),
 'filter':()=>{S.filter=value;S.mapCenter=null;render();},'favorites':()=>{S.onlyFavorites=!S.onlyFavorites;render();},
 'favorite':()=>{S.favorites=S.favorites.includes(id)?S.favorites.filter(x=>x!==id):[...S.favorites,id];saveFavorites();render();},
 'view-run':()=>{S.selectedRun=id;closeModal();S.mapCenter=null;render();fitMap();},
 'board-modal':()=>boardModal(id),'review-modal':()=>reviewModal(id),'topup-modal':topupModal,'vt-modal':vtModal,
 'fit-map':fitMap,'clear-points':()=>{S.points=[];S.plan=null;render();},
 'remove-point':()=>{S.points.splice(Number(button.dataset.index),1);S.plan=null;render();},
 'quick-value':()=>{$('input[name=valor]',modal).value=Number(value).toFixed(2);},
 'rate':()=>{S.rating=Number(value);modal.querySelectorAll('[data-action=rate]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.value)<=S.rating);b.setAttribute('aria-pressed',String(Number(b.dataset.value)===S.rating));});$('#rating-label').textContent=S.rating+' de 5 estrelas';},
 'review-occupancy':()=>{S.reviewOccupancy=value;$('#review-occupancy').innerHTML=LOTACOES_HTML('review-occupancy',value);},
 'payment-method':()=>{S.paymentMethod=value;modal.querySelectorAll('[data-action=payment-method]').forEach(b=>b.classList.toggle('active',b.dataset.value===value));$('#installments-field').hidden=value!=='credito';if(value!=='credito')$('select[name=parcelas]',modal).value='1';$('#payment-note').textContent=value==='pix'?'Não geramos cobrança ou código PIX real. Nenhum dinheiro será transferido.':'Não informe número de cartão ou CVV. Este fluxo apenas registra um crédito demonstrativo; não faz cobrança.';}
};if(immediate[act]){e.preventDefault();immediate[act]();return;}e.preventDefault();action(async()=>{
 if(act==='nav')return navigate(button.dataset.tab);
 if(act==='refresh'){await refresh(true);toast('Viagens atualizadas.');}
 if(act==='locate')await locate();
 if(act==='calculate-route'||act==='save-points'){S.plan=await api('percursos',{pontos:S.points,calcular_vias:act==='calculate-route'});render();fitMap();toast(act==='calculate-route'?'Percurso viário de referência salvo.':'Pontos salvos sem desenhar uma linha viária.');}
 if(act==='logout'){stopWatches();await api('sair',{});S.user=null;S.me=null;S.runs=[];S.wallet=null;S.points=[];S.plan=null;S.reviews=[];S.selectedRun=null;closeModal();render();}
 if(act==='start-gps')await shareGPS();
 if(act==='stop-gps'){const v=S.me?.viagem;stopWatches();if(v)await api('viagens/'+v.id+'/parar-gps',{});await refresh(true);toast('Compartilhamento de GPS interrompido.');}
 if(act==='end-run'){if(!confirm('Encerrar esta viagem? O GPS será removido e os embarques ativos serão finalizados.'))return;stopWatches();await api('viagens/'+id+'/encerrar',{});await refresh(true);toast('Viagem encerrada.');}
 if(act==='driver-occupancy'){await api('viagens/'+id+'/lotacao',{lotacao:value});await refresh(true);toast('Lotação declarada atualizada.');}
 if(act==='report-occupancy'){await api('embarques/'+id+'/lotacao',{lotacao:value});toast('Seu relato de lotação foi registrado.');await refresh(true);}
 if(act==='disembark'){arrival(false);const b=await api('embarques/'+id+'/desembarcar',{});await refresh(true);toast('Desembarque registrado.');reviewModal(b.id);}
},button);});
document.addEventListener('submit',e=>{const form=e.target;if(!['auth-form','start-run-form','board-form','review-form','topup-form','vt-form'].includes(form.id))return;e.preventDefault();const f=new FormData(form);const button=form.querySelector('button[type=submit]');action(async()=>{
 if(form.id==='auth-form'){const payload={email:f.get('email'),senha:f.get('senha')};if(S.authMode==='criar'){payload.nome=f.get('nome');payload.perfil=S.authRole;}const data=await api(S.authMode==='criar'?'contas':'entrar',payload);S.user=data.conta;S.tab='explorar';S.mapCenter=null;readFavorites();await refresh(true);loadWeather();}
 if(form.id==='start-run-form'){S.planLine=f.get('linha_id');await api('viagens',{linha_id:f.get('linha_id'),veiculo:f.get('veiculo'),sentido:f.get('sentido'),percurso_id:S.plan?.id||null});S.tab='viagem';S.mapCenter=null;await refresh(true);toast('Viagem aberta. Compartilhe o GPS somente se desejar.');}
 if(form.id==='board-form'){const payload={viagem_id:form.dataset.id};if(f.has('origem')){payload.ponto_embarque=Number(f.get('origem'));payload.ponto_desembarque=Number(f.get('destino'));}await api('embarques',payload);S.tab='viagem';S.mapCenter=null;closeModal();await refresh(true);toast('Embarque declarado registrado. Nenhuma passagem foi cobrada.');}
 if(form.id==='review-form'){if(!S.rating)throw Error('Escolha de 1 a 5 estrelas.');await api('embarques/'+form.dataset.id+'/avaliar',{nota:S.rating,descricao:f.get('descricao'),lotacao:S.reviewOccupancy});closeModal();await refresh(true);toast('Avaliação registrada. Obrigado por compartilhar sua experiência!');}
 if(form.id==='topup-form'){const response=await api('carteira/recarga-demo',{valor_centavos:cents(f.get('valor')),metodo:S.paymentMethod,parcelas:Number(f.get('parcelas')||1),chave_idempotencia:S.paymentKey});closeModal();S.tab='carteira';await refresh(true);toast(response.repeticao?'Esta solicitação já estava registrada; não duplicamos o crédito.':'Crédito de demonstração registrado. Nenhuma cobrança real foi feita.');}
 if(form.id==='vt-form'){await api('carteira/vt-demo',{valor_centavos:cents(f.get('valor')),empresa:f.get('empresa'),chave_idempotencia:S.paymentKey});closeModal();S.tab='carteira';await refresh(true);toast('Lançamento de VT simulado registrado. Não houve depósito de empresa.');}
 },button);});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('pagehide',()=>{const id=S.me?.viagem?.id;if(S.gpsSharing&&id){fetch('/web-api/viagens/'+id+'/parar-gps',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}',keepalive:true}).catch(()=>{});}stopWatches();});
async function boot(){try{const [config,catalog]=await Promise.all([api('configuracao'),api('linhas')]);S.config=config;S.lines=catalog.linhas;try{const data=await api('me');S.user=data.conta;S.me=data;readFavorites();S.runs=(await api('viagens')).viagens;}catch(e){if(e.status!==401)throw e;}render();if(S.user)loadWeather();}catch(e){app.innerHTML=`<div class="boot"><span class="logo-mark">T<span>${icon('arrow')}</span></span><h1>Vamos reconectar?</h1><p style="padding:0 25px;text-align:center">${esc(e.message)}</p><button class="btn" data-action="reload">Tentar novamente</button><p class="small">Confira se o terminal da API continua aberto.</p></div>`;}setInterval(()=>{if(S.user)refresh(false);},10000);}
boot();
})();
